import React, { useState } from "react";

function ApplicationsTable({ applications }) {
  const [selectedApp, setSelectedApp] = useState(null);

  return (
    <div style={containerStyle}>
      {applications.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No applications received yet.</p>
      ) : (
        <table style={tableStyle}>
          <thead style={theadStyle}>
            <tr>
              <th style={thStyle}>Name</th>
              <th style={thStyle}>E-mail Id</th>
              <th style={thStyle}>Phone Number</th>
              <th style={thStyle}>Resume</th>
              <th style={thStyle}>Skill Set</th>
              <th style={thStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {applications.map((app) => (
              <tr key={app._id} style={trStyle}>
                <td style={tdStyle}>{app.name || "NA"}</td>
                <td style={tdStyle}>{app.email || "NA"}</td>
                <td style={tdStyle}>{app.phone || "NA"}</td>
                <td style={tdStyle}>
                  {app.resumeUrl ? (
                    <a href={app.resumeUrl} target="_blank" rel="noopener noreferrer">View Resume</a>
                  ) : "NA"}
                </td>
                <td style={tdStyle}>{app.skillset || "NA"}</td>
                <td style={tdStyle}>
                  <button style={btnStyle} onClick={() => setSelectedApp(app)}>
                    View Full Details
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* Modal for full details */}
      {selectedApp && (
        <div style={modalOverlay}>
          <div style={modalContainer}>
            <h2>Application Details</h2>
            <p><b>Name:</b> {selectedApp.name || "NA"}</p>
            <p><b>Email:</b> {selectedApp.email || "NA"}</p>
            <p><b>Phone:</b> {selectedApp.phone || "NA"}</p>
            <p><b>Skillset:</b> {selectedApp.skillset || "NA"}</p>
            <p>
              <b>Resume:</b>{" "}
              {selectedApp.resumeUrl ? (
                <a href={selectedApp.resumeUrl} target="_blank" rel="noopener noreferrer">View Resume</a>
              ) : "NA"}
            </p>
            <button style={btnStyle} onClick={() => setSelectedApp(null)}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

// --- Styles ---
const containerStyle = {
  background: "#fff",
  borderRadius: "12px",
  padding: "25px",
  boxShadow: "0 3px 15px rgba(0,0,0,0.05)",
  overflowX: "auto",
};

const tableStyle = { width: "100%", borderCollapse: "collapse" };
const theadStyle = { backgroundColor: "#f1f5f9" };
const thStyle = { textAlign: "left", padding: "12px 16px", fontSize: "14px" };
const tdStyle = { padding: "12px 16px", fontSize: "14px" };
const trStyle = { borderTop: "1px solid #e2e8f0" };
const btnStyle = {
  padding: "6px 12px",
  background: "#2563eb",
  color: "#fff",
  border: "none",
  borderRadius: "6px",
  cursor: "pointer",
};

// Modal Styles
const modalOverlay = {
  position: "fixed",
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  background: "rgba(0,0,0,0.6)",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  zIndex: 1000,
};

const modalContainer = {
  background: "#fff",
  padding: "24px",
  borderRadius: "12px",
  width: "90%",
  maxWidth: "500px",
};

export default ApplicationsTable;
